⚠️糯叽馆首发🆘严禁二传至别的饭馆❗️🚫❗️
*/
:root {
   /* ========================================
      【顶部导航栏】
      ======================================== */
   --chat-header-bg: transparent;
   --chat-header-border: transparent;
   --chat-header-title-color: #1c1c1e;
