   --chat-header-subtitle-size: 11px;
   --chat-header-icon-color: #1c1c1e;
   --chat-header-height: auto;

   /* ========================================
      【未读小红点/数字徽章】
      ======================================== */
   --unread-bg: #ff3b30;
   --chat-header-unread-bg: #ff3b30;
   --chat-header-unread-size: 8px;
   --chat-header-unread-border: 2px solid #f2f2f7;
   --chat-header-unread-num-bg: #ff3b30;
   --chat-header-unread-num-color: #fff;

   /* ========================================
      【时间戳/日期/旁白/系统消息】
      ======================================== */
   --timestamp-color: #8e8e93;
   --date-divider-color: #8e8e93;
   --narration-color: #8e8e93;
   --system-msg-color: #8e8e93;
   --na-bg: transparent;
   --na-bd: none;

   /* ========================================
      【翻译内容】
      ======================================== */
   --trans-detached-bg: #ffffff;
   --trans-detached-color: #1c1c1e;
   --trans-btn1: #c7c7cc;
   --translation-size: 14px;
   --translation-text-color: #8e8e93;
   --translation-line-height: 1.4;
   --translation-bg: transparent;
   --translation-padding: 0;
   --translation-radius: 0;

   /* ========================================
      【回复预览栏（输入框上方）】
      ======================================== */
   --reply-bar-accent: #8e8e93;
   --reply-bar-text-color: #8e8e93;

   --reply-detached-bg: rgba(0,0,0,0.04);
   --reply-detached-radius: 10px;
   --reply-detached-padding: 6px 10px;
   --reply-detached-border: none;
   --reply-detached-text-color: #8e8e93;
   --reply-detached-name-color: #007aff;
   --reply-detached-max-width: 100%;
   --reply-detached-margin-top: 4px;

   /* ========================================
      【我方消息气泡】🍏by面面冰🐰🚫二传
      深色呼吸感渐变 + 白体文字
      ======================================== */
   --bubble-me-bg: linear-gradient(155deg, rgba(55,55,58,0.90) 0%, rgba(22,22,26,0.86) 100%);
   --bubble-me-bg-gradient: initial;
   --bubble-me-color: #ffffff;
   --bubble-me-font-size: 16px;
   --bubble-me-line-height: 1.35;
   --bubble-me-padding: 9px 14px;
   --bubble-me-radius: 20px;
   --bubble-me-shadow: 0 1px 2px rgba(0,0,0,0.05);
   --bubble-me-border: none;
   --bubble-me-link-color: #0a84ff;
   --bubble-me-backdrop: none;

   /* mynd风格：我方尖角统一右上角 */
   --bubble-me-radius-first: 6px 20px 20px 20px;
   --bubble-me-radius-mid: 6px 20px 20px 20px;
   --bubble-me-radius-last: 6px 20px 20px 20px;

   /* ========================================
      【对方消息气泡】🍎by面面冰🐰🚫二传
      ======================================== */
   --bubble-them-bg: #FFFFFF;
   --bubble-them-bg-gradient: initial;
   --bubble-them-color: #1c1c1e;
   --bubble-them-font-size: 16px;
   --bubble-them-line-height: 1.35;
   --bubble-them-padding: 9px 14px;
   --bubble-them-radius: 20px;
   --bubble-them-shadow:none;
   --bubble-them-border:none;
   --bubble-them-link-color: #007aff;
   --bubble-them-backdrop: none;

   /* mynd风格：对方尖角统一左上角 */
   --bubble-them-radius-first: 20px 6px 20px 20px;
   --bubble-them-radius-mid: 20px 6px 20px 20px;
   --bubble-them-radius-last: 20px 6px 20px 20px;

   /* ========================================
      【语音消息】
      我方波形适配深色气泡：白色波形
