   --voice-duration-size: 12px;
   --voice-me-bar-active: #ffffff;
   --voice-me-bar-inactive: rgba(255,255,255,0.35);
   --voice-them-bar-active: #1c1c1e;
   --voice-them-bar-inactive: rgba(0,0,0,0.2);

   /* ========================================
      【底部输入区域】
      ======================================== */
   --input-area-bg: transparent;
   --input-area-blur: 0px;
   --input-area-border-top: transparent;
   --input-area-padding: 8px 8px 30px;

   /* ========================================
      【输入框胶囊】by面面冰🐰🚫二传
      ======================================== */
   --input-box-bg: transparent;
   --input-box-color: #1c1c1e;
   --input-box-placeholder: #8e8e93;
   --input-box-radius: 22px;
   --input-box-padding: 9px 16px;
   --input-box-font-size: 16px;
   --input-box-border: none;
   --input-box-blur: none;
   --input-box-shadow: none;
   --input-caret-color: #007aff;

   /* ========================================
      【底栏按钮图标】
      ======================================== */
   --icon-img-1: none;
   --icon-img-2: none;
   --icon-img-3: none;
   --icon-img-4: none;

   --plus-btn-bg: transparent;
   --input-btn-plus-bg: transparent;

   /* ========================================
      【发送按钮】
      ======================================== */
   --send-btn-bg: #fffecf2;
   --send-btn-color: #fdb2c7;
   --send-btn-shadow: 0 2px 8px rgba(253,178,199,0.4);

   /* ========================================
      【更多功能面板】
      ======================================== */
   --more-options-bg: rgba(255,255,255,0.9);
   --more-options-blur: blur(30px) saturate(180%);
