   --more-options-color: #1c1c1e;
   --more-options-divider: rgba(0,0,0,0.06);

   /* ========================================
      【打字指示器】
      ======================================== */
   --typing-bg: #ffffff;
   --typing-radius: 18px;
   --typing-dot-size: 6px;
   --typing-dot-color: #8e8e93;

   /* ========================================
      【已读状态文字】
      ======================================== */
   --status-color: #8e8e93;
   --status-size: 10px;
   --status-opacity: 0.8;
   --status-read-color: #8e8e93;
}


/* ============================================
