.header-btn-phone svg,
.header-btn-video svg,
.header-btn-info svg {
    width: 20px !important;
    height: 20px !important;
    stroke: var(--chat-header-icon-color) !important;
    stroke-width: 2 !important;
}

/* 按钮间距 */
.header-action-btn {
    gap: 12px !important;
}


/* ========== 消息区域 ========== */
/* ✨ position:fixed 让消息列表撑满全屏，顶栏底栏浮在它上面 by面面冰🐰🚫二传 */
.chat-messages-area {
    position: fixed !important;
    top: 0 !important;
    bottom: 0 !important;
    left: 0 !important;
    right: 0 !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch !important;
    z-index: 1 !important;
}

/* ✨ padding-top/bottom 让首尾消息不被顶栏底栏挡住，滚动时消息会滑入这些区域 */
/* top≈100px 对应顶栏高度(50+36+8≈94px) + 少量间距 */
/* bottom≈85px 对应底栏高度(8+40+30≈78px) + 少量间距 */
/* 如果间距不合适可以微调这两个值 */
.chat-message-list-custom {
    gap: 2px !important;
    padding: 100px 16px 85px !important;
    background: transparent !important;
}

/* 系统消息/时间戳/日期/旁白 */
.msg-system,
.timestamp-custom,
.date-divider-custom,
.msg-narration-custom,
.system-message-custom {
    width: fit-content !important;
    font-size: 12px !important;
    font-style: normal !important;
    font-weight: var(--font-weight) !important;
    line-height: 1.3 !important;
    padding: 4px 10px !important;
    margin: 8px auto 12px auto !important;
    background: transparent !important;
    border-radius: 10px !important;
