    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 3px !important;
}
:is(.bubble-me-custom, .bubble-them-custom):has(:is(.msg-transfer-card, .msg-videocall-card, .msg-loc-card, .msg-sim-card, .gift-ig-container))::before,
:is(.bubble-me-custom, .bubble-them-custom):has(:is(.msg-transfer-card, .msg-videocall-card, .msg-loc-card, .msg-sim-card, .gift-ig-container))::after {
    display: none !important;
}

/* 正常发的图片/表情包去掉气泡背景 */
:is(.bubble-me-custom, .bubble-them-custom):has(> img) {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 3px !important;
}
:is(.bubble-me-custom, .bubble-them-custom):has(> img)::before,
:is(.bubble-me-custom, .bubble-them-custom):has(> img)::after {
    display: none !important;
}

/* 已读状态文字 */
.msg-status-custom {
