    color: var(--status-color) !important;
    opacity: var(--status-opacity) !important;
}

/* ========== 底部输入区域 ========== */
/* ✨ position:fixed 让底栏脱离文档流，浮在消息上方 */
/* ✨ 整体完全透明，消息可穿过；只有输入框胶囊和按钮圆圈有雾面玻璃 by面面冰🐰🚫二传*/
.input-area-custom {
    position: fixed !important;
    bottom: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 100 !important;
    background: transparent !important;
