.msg-videocall-card > div:first-child svg * {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
}

/* 用mask画电话图标 */
.msg-videocall-card > div:first-child::before {
    content: "" !important;
    display: block !important;
    width: 18px !important;
    height: 18px !important;
    background: var(--call-icon-color) !important;
