    mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='currentColor' d='M20 15.5c-1.25 0-2.45-.2-3.57-.57-.35-.11-.74-.03-1.02.24l-2.2 2.2c-2.83-1.44-5.15-3.75-6.59-6.59l2.2-2.21c.28-.27.36-.66.25-1.01-.37-1.12-.57-2.32-.57-3.57 0-.55-.45-1-1-1H4c-.55 0-1 .45-1 1 0 9.39 7.61 17 17 17 .55 0 1-.45 1-1v-3.5c0-.55-.45-1-1-1z'/></svg>") center / contain no-repeat !important;
}

/* ========== 文字区域 ========== */
.msg-videocall-card > div:nth-child(2) {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important;
    max-width: none !important;
    gap: 4px !important;
    white-space: nowrap !important;
    flex-shrink: 1 !important;
    min-width: 0 !important;
}

/* 主文字（状态） */
.msg-videocall-card > div:nth-child(2) > div:first-child {
    font-weight: var(--font-weight, 400) !important;
    letter-spacing: 0 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    margin: 0 !important;
    font-size: 0 !important;
}

/* 默认状态文字 */
.msg-videocall-card > div:nth-child(2) > div:first-child::before {
    font-size: 16px !important;
    font-weight: var(--font-weight, 400) !important;
    line-height: 1.35 !important;
    content: "通话已结束" !important;
}

/* 我方取消 */
.bubble-me-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.bubble-me-custom .msg-videocall-card.cancelled > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card.cancelled > div:nth-child(2) > div:first-child::before {
    content: "已取消" !important;
}

/* 对方取消 */
.bubble-them-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.bubble-them-custom .msg-videocall-card.cancelled > div:nth-child(2) > div:first-child::before,
.bubble-them-custom .msg-videocall-card.rejected > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.cancelled > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.rejected > div:nth-child(2) > div:first-child::before {
    content: "对方已取消" !important;
}

/* 通话接通 - 显示时长 */
.msg-videocall-card.connected > div:nth-child(2) > div:first-child::before {
    content: "通话时长 " !important;
}

/* 我方文字颜色 */
.bubble-me-custom .msg-videocall-card > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card > div:nth-child(2) > div:first-child::before {
    color: var(--call-bubble-me-text) !important;
    -webkit-text-fill-color: var(--call-bubble-me-text) !important;
}

/* 对方文字颜色 */
.bubble-them-custom .msg-videocall-card > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card > div:nth-child(2) > div:first-child::before {
    color: var(--call-bubble-them-text) !important;
    -webkit-text-fill-color: var(--call-bubble-them-text) !important;
}

/* 时长（仅connected状态显示） */
.msg-videocall-card > div:nth-child(2) > div:nth-child(2) {
    display: none !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) {
    display: inline-flex !important;
    visibility: visible !important;
    opacity: 1 !important;
    width: auto !important;
    height: auto !important;
    font-size: 16px !important;
    font-weight: var(--font-weight, 400) !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    gap: 0 !important;
    letter-spacing: 0 !important;
    line-height: 1.35 !important;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) * {
    display: inline !important;
    visibility: visible !important;
    opacity: 1 !important;
    width: auto !important;
    height: auto !important;
    font-size: 16px !important;
