    height: 16px !important;
    background: #ffffff !important;
    -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='currentColor' d='M12 4l-8 8h5v8h6v-8h5z'/></svg>") center / contain no-repeat !important;
    mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path fill='currentColor' d='M12 4l-8 8h5v8h6v-8h5z'/></svg>") center / contain no-repeat !important;
}

/* 输入文字时，隐藏AI按钮显示发送 */
.input-btns-right:has(.send-btn-custom) .input-btn-ai {
