}

/* ========== 更多功能弹出面板 ========== */
.more-options-popup {
    background: var(--more-options-bg) !important;
    backdrop-filter: var(--more-options-blur) !important;
    -webkit-backdrop-filter: var(--more-options-blur) !important;
