    z-index: 200 !important;
}

.more-options-item-row {
    color: var(--more-options-color) !important;
    padding: 12px !important;
    border-radius: 12px !important;
}

/* ========== 表情反应条 ========== */
.reaction-bar {
    background: rgba(255,255,255,0.9) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    border-radius: 999px !important;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1) !important;
    border: 1px solid rgba(255,255,255,0.8) !important;
    padding: 6px 8px !important;
    z-index: 200 !important;
}

/* ========== 长按菜单 ========== */
.ig-context-menu {
    background: rgba(255,255,255,0.95) !important;
    backdrop-filter: blur(30px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(30px) saturate(180%) !important;
    border-radius: 14px !important;
    box-shadow: 0 10px 40px rgba(0,0,0,0.15) !important;
    overflow: hidden !important;
    z-index: 200 !important;
}

.ig-menu-item {
    padding: 12px 16px !important;
}

/* ========== 打字指示器 ========== */
.nuo-typing-bubble {
    background: var(--typing-bg) !important;
    border-radius: var(--typing-radius) !important;
    border-bottom-left-radius: 6px !important;
    padding: 12px 16px !important;
    box-shadow: 0 1px 2px rgba(0,0,0,0.05) !important;
}

.nuo-typing-indicator .typing-dot {
    width: var(--typing-dot-size) !important;
    height: var(--typing-dot-size) !important;
    background: var(--typing-dot-color) !important;
}

/* ========== 隐藏滚动条，保持干净 ========== */
.chat-messages-area::-webkit-scrollbar {
    display: none !important;
}
.chat-messages-area {
    scrollbar-width: none !important;
}

/* ========== 翻译独立气泡（隐藏，只保留气泡内翻译） ========== */
.msg-translation-detached {
    display: none !important;
}

.msg-translation-detached-content {
    background: var(--trans-detached-bg) !important;
    color: var(--trans-detached-color) !important;
    padding: 8px 12px !important;
    border-radius: 12px !important;
    font-size: 14px !important;
    line-height: 1.4 !important;
}

/* ========== 引用/回复块 ========== */
.msg-reply-block {
    display: none !important;
}

/* ========== 引用/回复块 - 磨砂质感 ========== */
.msg-reply-block-detached {
    display: flex !important;
    align-items: center !important;
    background: rgba(255, 255, 255, 0.55) !important;
    backdrop-filter: blur(8px) saturate(120%) !important;
    -webkit-backdrop-filter: blur(8px) saturate(120%) !important;
    border-radius: 10px !important;
    padding: 6px 10px !important;
    border: 0.5px solid rgba(255, 255, 255, 0.2) !important;
    gap: 8px !important;
}

/* 引用名称 + 文字 统一色号 */
.msg-reply-detached-name,
.msg-reply-detached-text {
    color: #6c6c70 !important;
    font-size: 13px !important;
}

.msg-reply-detached-name {
    flex-shrink: 0 !important;
}

.msg-reply-detached-text {
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    min-width: 0 !important;
}

.msg-reply-detached-name::after {
    content: "：" !important;
}

.msg-reply-block-detached img {
    width: 35px !important;
    height: 35px !important;
    object-fit: cover !important;
    flex-shrink: 0 !important;
    border-radius: 4px !important;
}

.msg-reply-detached-them {
    align-self: flex-start !important;
    margin-left: 4.5px !important;
}

.msg-reply-detached-me {
    align-self: flex-end !important;
    margin-right: 4.5px !important;
}

/* 加号按钮上移 5px by面面冰🐰🚫二传*/
.input-btn-plus {
    transform: translateY(-5px) !important;
}
/* ========== 图片消息 ========== */
.msg-image-wrapper img {
    max-width: 150px !important;
    max-height: 280px !important;
    width: auto !important;
    height: auto !important;
    object-fit: contain !important;
    border-radius: 12px !important;
    display: block !important;
}
/* 我方图片右对齐，对方图片左对齐（防止横长图偏位） */
.bubble-me-custom .msg-image-wrapper img {
    margin-left: auto !important;
    margin-right: 0 !important;
}
.bubble-them-custom .msg-image-wrapper img {
    margin-left: 0 !important;
    margin-right: auto !important;
}
/* 图片气泡去掉多余内边距和行高 */
:is(.bubble-me-custom, .bubble-them-custom):has(.msg-image-wrapper) {
    padding: 3px !important;
    line-height: 0 !important;
    font-size: 0 !important;
}
.msg-image-wrapper {
    line-height: 0 !important;
    font-size: 0 !important;
}
/* ========== 表情包 ========== */
/* 用 :not(:has()) 排除含 msg-image-wrapper 的气泡，剩下的就是表情包 */
/* 表情包保持比例缩小 */
:is(.bubble-me-custom, .bubble-them-custom):not(:has(.msg-image-wrapper)) img {
    max-width: 80px !important;
    height: auto !important;
    border-radius: 8px !important;
}
:root {
    /* 我方通话气泡 - 和气泡me完全统一（深色呼吸感） */
    --call-bubble-me-bg: linear-gradient(155deg, rgba(55,55,58,0.90) 0%, rgba(22,22,26,0.86) 100%);
    --call-bubble-me-text: #ffffff;
    /* 对方通话气泡 - 和气泡them完全统一 */
    --call-bubble-them-bg: #ffffff;
    --call-bubble-them-text: #1c1c1e;
    /* 通话图标颜色 */
    --call-icon-color: #8e8e93;
}

/* ========== 通话卡片主体 ========== */
/* 和普通气泡完全一样的风格：20px圆角、padding 9px 14px */
.msg-videocall-card,
.msg-videocall-card.missed,
.msg-videocall-card.connected,
.msg-videocall-card.cancelled,
.msg-videocall-card.rejected {
    width: fit-content !important;
    min-width: 0 !important;
    max-width: none !important;
    padding: 9px 14px !important;
    border-radius: 20px !important;
    box-shadow: 0 1px 2px rgba(0,0,0,0.05) !important;
    border: none !important;
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    position: relative !important;
    cursor: default !important;
    background: var(--call-bubble-them-bg) !important;
}

/* 我方通话气泡 - 深色呼吸感 */
.bubble-me-custom .msg-videocall-card,
.msg-me .msg-videocall-card {
    background: var(--call-bubble-me-bg) !important;
}

/* 我方通话气泡：尖角右上角 */
.bubble-me-custom .msg-videocall-card,
.bubble-me-custom .msg-videocall-card.missed,
.bubble-me-custom .msg-videocall-card.connected,
.bubble-me-custom .msg-videocall-card.cancelled,
.bubble-me-custom .msg-videocall-card.rejected,
.msg-me .msg-videocall-card,
.msg-me .msg-videocall-card.missed,
.msg-me .msg-videocall-card.connected,
.msg-me .msg-videocall-card.cancelled,
.msg-me .msg-videocall-card.rejected {
    border-radius: 18px 3px 18px 18px !important;
}

/* 对方通话气泡：尖角左上角 */
.bubble-them-custom .msg-videocall-card,
.bubble-them-custom .msg-videocall-card.missed,
.bubble-them-custom .msg-videocall-card.connected,
.bubble-them-custom .msg-videocall-card.cancelled,
.bubble-them-custom .msg-videocall-card.rejected,
.msg-them .msg-videocall-card,
.msg-them .msg-videocall-card.missed,
.msg-them .msg-videocall-card.connected,
.msg-them .msg-videocall-card.cancelled,
.msg-them .msg-videocall-card.rejected {
    border-radius: 3px 18px 18px 18px !important;
}

/* 我方通话图标 - 白色，适配深色气泡 */
.bubble-me-custom .msg-videocall-card > div:first-child::before,
.msg-me .msg-videocall-card > div:first-child::before {
    background: rgba(255,255,255,0.88) !important;
}

/* ========== 通话图标 ========== */
.msg-videocall-card > div:first-child {
    width: 20px !important;
    height: 20px !important;
    min-width: 20px !important;
    min-height: 20px !important;
    border-radius: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    flex-shrink: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 0 !important;
    color: transparent !important;
}

/* 隐藏原生SVG */
.msg-videocall-card > div:first-child svg,
.msg-videocall-card > div:first-child svg * {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
}

/* 用mask画电话图标 */
.msg-videocall-card > div:first-child::before {
    content: "" !important;
    display: block !important;
    width: 18px !important;
