/* =========================================
   气泡
   ========================================= */

/* ---------- 我方气泡（右侧） ---------- */
.bubble-me-custom {
  --bubble-bg: #E5F0FF;
  --bubble-border: #D0D8E2;
  position: relative !important;
  background: var(--bubble-bg) !important;
  color: #424242 !important;
  border: 1px solid var(--bubble-border) !important;
  border-radius: 4px !important;
  padding: 7px 12px !important;
}

.bubble-me-custom::after {
  content: "" !important;
  position: absolute !important;
  right: -5px !important;
  top: 12px !important;
  width: 7px !important;
  height: 7px !important;
  background: var(--bubble-bg) !important;
  border-right: 1px solid var(--bubble-border) !important;
  border-top: 1px solid var(--bubble-border) !important;
  transform: rotate(45deg) !important;
  z-index: 1 !important;
}

/* ---------- 对方气泡（左侧） ---------- */
.bubble-them-custom {
  --bubble-bg: #f9f9f9;
  --bubble-border: #E5E5E5;
  position: relative !important;
  background: var(--bubble-bg) !important;
  color: #424242 !important;
  border: 1px solid var(--bubble-border) !important;
  border-radius: 4px !important;
  padding: 7px 12px !important;
}

.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  left: -5px !important;
  top: 12px !important;
  width: 7px !important;
  height: 7px !important;
  background: var(--bubble-bg) !important;
  border-left: 1px solid var(--bubble-border) !important;
  border-bottom: 1px solid var(--bubble-border) !important;
  transform: rotate(45deg) !important;
  z-index: 1 !important;
}

/* =========================================
   特殊消息 - 统一结构
   ========================================= */

/* 1. 去掉气泡背景和内边距 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container) {
