}

/* 2. 文字/图标颜色控制（用变量） */
.msg-them .msg-transfer-card,
.msg-them .msg-transfer-card *,
.msg-them .msg-loc-card,
.msg-them .msg-loc-card *,
.msg-them .gift-ig-container,
