}
.msg-me .voice-duration {
  color: var(--me-wave-active, #666C75) !important;
}

/* 4. 图片消息文字 */
.msg-them .msg-image-wrapper * {
  color: var(--them-card-text, #333333) !important;
}
.msg-me .msg-image-wrapper * {
  color: var(--me-card-text, #666C75) !important;
}

